  async function handleAdminModalForm(form,data,msg){
    const name=form.dataset.formName;
    const editId=form.dataset.editId?Number(form.dataset.editId):0;
    if(name==="student-edit"){
      await api(`/api/admin/students/${editId}`,{method:"PATCH",body:JSON.stringify({full_name:data.full_name,phone:data.phone||null,preferred_language:data.preferred_language,dob:data.dob,status:data.status,is_active:data.is_active?1:0,is_blocked:data.is_blocked?1:0})});
    } else if(name==="course"){
      const body={...data,category_id:data.category_id?Number(data.category_id):undefined,is_visible:!!data.is_visible};
      await api(editId?`/api/admin/courses/${editId}`:"/api/admin/courses",{method:editId?"PATCH":"POST",body:JSON.stringify(body)});
    } else if(name==="batch"){
      const course=form.dataset.courseId||state.query.get("course_id")||"";if(!course)throw new Error("Course ID required.");
      await api(editId?`/api/admin/course-batches/${editId}`:`/api/admin/courses/${Number(course)}/batches`,{method:editId?"PATCH":"POST",body:JSON.stringify(data)});
    } else if(name==="question"){
      const body={...data,marks:Number(data.marks||0),negative_marks:Number(data.negative_marks||0),subject_id:data.subject_id?Number(data.subject_id):undefined,chapter_id:data.chapter_id?Number(data.chapter_id):undefined,topic_id:data.topic_id?Number(data.topic_id):undefined,course_id:data.course_id?Number(data.course_id):undefined,source_year:data.source_year?Number(data.source_year):undefined,media_id:data.media_id?Number(data.media_id):undefined,is_active:data.is_active?1:0,tags:String(data.tags||"").split(",").map(x=>x.trim()).filter(Boolean)};
      body.translations=["as","hi"].map(lang=>{const q=String(data[`translation_${lang}_question_text`]||"").trim();const item={language:lang,question_text:q};for(const k of ["option_a","option_b","option_c","option_d","option_e","explanation","model_answer"])item[k]=data[`translation_${lang}_${k}`]||"";return item;}).filter(t=>t.question_text||["option_a","option_b","option_c","option_d","option_e","explanation","model_answer"].some(k=>String(t[k]||"").trim()));
      for(const key of Object.keys(body))if(key.startsWith("translation_"))delete body[key];
      await api(editId?`/api/admin/questions/${editId}`:"/api/admin/questions",{method:editId?"PATCH":"POST",body:JSON.stringify(body)});
    } else if(name==="exam"){
      const body={...data,course_id:Number(data.course_id),duration_minutes:Number(data.duration_minutes||0),total_questions:Number(data.total_questions||0),total_marks:Number(data.total_marks||0),pass_percentage:Number(data.pass_percentage||0),attempt_limit:Number(data.attempt_limit||1),negative_marking_enabled:!!data.negative_marking_enabled,randomize_questions:!!data.randomize_questions,randomize_options:!!data.randomize_options,allow_retake:!!data.allow_retake};
      await api(editId?`/api/admin/exams/${editId}`:"/api/admin/exams",{method:editId?"PATCH":"POST",body:JSON.stringify(body)});
    } else if(name==="assignment"){await api("/api/admin/assignments",{method:"POST",body:JSON.stringify({...data,total_marks:Number(data.total_marks||0),passing_marks:Number(data.passing_marks||0),subject_id:Number(data.subject_id),chapter_id:Number(data.chapter_id),topic_id:data.topic_id?Number(data.topic_id):undefined,course_id:data.course_id?Number(data.course_id):undefined,duration_minutes:data.duration_minutes?Number(data.duration_minutes):undefined,max_attempts:Number(data.max_attempts||1),is_free:!!data.is_free,allow_late_submission:!!data.allow_late_submission})});}
    else if(name==="announcement"){await api("/api/admin/announcements",{method:"POST",body:JSON.stringify(data)});}
    else if(name==="pricing"){await api("/api/admin/pricing/products",{method:"POST",body:JSON.stringify({...data,product_id:Number(data.product_id),base_price:Number(data.base_price)})});}
    else if(name==="coupon"){await api("/api/admin/pricing/coupons",{method:"POST",body:JSON.stringify({...data,discount_value:Number(data.discount_value),is_active:!!data.is_active})});}
    else if(name==="refund"){await api("/api/admin/refunds",{method:"POST",body:JSON.stringify({payment_id:Number(data.payment_id),amount:data.amount?Number(data.amount):undefined})});}
    else if(name==="publish"){await api(`/api/admin/publishing/${encodeURIComponent(data.entity_type)}/${Number(data.entity_id)}/publish`,{method:"POST",body:JSON.stringify({starts_at:data.starts_at||undefined,ends_at:data.ends_at||undefined})});}
    else if(name.startsWith("content:")){const title=name.split(":")[1];const endpoint=title==="Notes"?"/api/admin/notes":"/api/admin/videos";await api(editId?`${endpoint}/${editId}`:endpoint,{method:editId?"PATCH":"POST",body:JSON.stringify(data)});}
    else if(name.startsWith("tax:")){const type=name.split(":")[1];const endpoint=type==="subject"?"/api/admin/taxonomy/subjects":type==="chapter"?"/api/admin/taxonomy/chapters":"/api/admin/taxonomy/topics";await api(endpoint,{method:"POST",body:JSON.stringify(data)});}
    else throw new Error(`Unsupported form: ${name}`);
    msg.innerHTML=alert(editId?"Updated successfully.":"Saved successfully.","success");setTimeout(()=>{closeModal();render();},450);
  }
  async function openPayment(order){const src="https://checkout.razorpay.com/v1/checkout.js";if(!window.Razorpay){await new Promise((resolve,reject)=>{const s=document.createElement("script");s.src=src;s.onload=resolve;s.onerror=()=>reject(new Error("Could not load payment checkout."));document.head.appendChild(s);});}if(!window.Razorpay)throw new Error("Payment checkout unavailable.");const key=str(order,"key_id","key"),providerOrder=str(order,"provider_order_id","razorpay_order_id");if(!key||!providerOrder)throw new Error("Payment order was created without provider checkout details.");const r=new window.Razorpay({key,amount:Number(order.amount||0),currency:str(order,"currency")||"INR",order_id:providerOrder,name:"Science Point Assam",handler:async response=>{try{await api("/api/payments/verify",{method:"POST",body:JSON.stringify({order_id:order.order_id,provider_order_id:response.razorpay_order_id,provider_payment_id:response.razorpay_payment_id,signature:response.razorpay_signature})});window.alert("Payment verified. Access will open from the central entitlement flow.");href("/student/purchases");}catch(e){window.alert(e instanceof Error?e.message:String(e));}}});r.open();}
